use serde_json::{json,Value};use sha2::{Digest,Sha256};
use std::{collections::BTreeMap,fmt::Write,fs,path::{Path,PathBuf},process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/golden-basis175";
const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-29-golden-basis175";
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn member(p:&Path)->Value {let bytes=fs::read(p).unwrap();let data=match String::from_utf8(bytes.clone()){Ok(v)=>json!({"encoding":"utf8","data":v}),Err(_)=>json!({"encoding":"hex","data":bytes.iter().map(|v|format!("{v:02x}")).collect::<String>()})};let mut v=data;v["sha256"]=json!(format!("{:x}",Sha256::digest(&bytes)));v["length"]=json!(bytes.len());v}
fn collect(root:&Path,dir:&Path,out:&mut BTreeMap<String,Value>){for e in fs::read_dir(dir).unwrap(){let p=e.unwrap().path();if p.is_dir(){collect(root,&p,out)}else{assert!(p.is_file());out.insert(p.strip_prefix(root).unwrap().display().to_string(),member(&p));}}}
fn archive(name:&str,members:&BTreeMap<String,Value>,dest:&Path){
    let bytes=serde_json::to_vec(members).unwrap();fs::write(r(format!("{name}.json")),&bytes).unwrap();
    let gz=Command::new("gzip").args(["-n","-c"]).arg(r(format!("{name}.json"))).output().unwrap();assert!(gz.status.success());let p=dest.join(format!("{name}.json.gz"));fs::write(&p,gz.stdout).unwrap();
    let back=Command::new("gzip").arg("-dc").arg(&p).output().unwrap();assert!(back.status.success());assert_eq!(back.stdout,bytes);
    let decoded:BTreeMap<String,Value>=serde_json::from_slice(&back.stdout).unwrap();
    for v in decoded.values(){let text=v["data"].as_str().unwrap();let b=if v["encoding"]=="utf8"{text.as_bytes().to_vec()}else{(0..text.len()).step_by(2).map(|i|u8::from_str_radix(&text[i..i+2],16).unwrap()).collect()};assert_eq!(json!(b.len()),v["length"]);assert_eq!(format!("{:x}",Sha256::digest(&b)),v["sha256"].as_str().unwrap());}
}
